    <script>
    import axios from "../../axios_instance";
    import { Form } from "vform"; 
    export default {
        props: {},
        components: {
            // VueRecaptcha, facebookLogin
        },
        data() {
            return {
                base_url: window.base_url,
                api_url: window.api_url,
                token: this.$localStorage.get("d_token"),
                user_data: JSON.parse(this.$localStorage.get("user")),
                role_id : '',
                items: [],   
                deptItems: [],   
                filterForm: new Form({ 
                    dept_id: "",
                    kra_id : "",
                    kpi_id : "",
                    quarter : "",
                    month : "",
                    show_kra: 1,
                    show_kpi: 1,
                    show_mos: 1,
                    show_yachi: 1,
                }),
                status: '',
                kraItem: [] ,  
                kpiItem: [] ,  
                mosItem: [] , 
            };
        },
        created() { 
            this.role_id = this.user_data.role_id ; 
            if( this.role_id == 5 || this.role_id == 6 || this.role_id == 7){
            this.filterForm.dept_id =   this.user_data.dept_id ; 
            this.getKRA();
            this.getItems(); 
            }else{
                this.getDept();
            } 
           
        },
        methods: {
            achievement(item , month){
                let target  = item.mostargetjoin[month] ;
                let achievement  = item.mosachievementjoin[month] ;
                if(target > 0 && achievement > 0 ){ 
                    return ((achievement/target)*100).toFixed()  ;
                }else {
                    return 0 ;
                }
                // if(item.mostargetjoin ? item.mostargetjoin[month] : 0 > 0  && item.mosachievementjoin ? item.mosachievementjoin[month]  : 0 > 0 ){
                //     return  ((item.mostargetjoin ? item.mostargetjoin[month] : 0 / item.mosachievementjoin ? item.mosachievementjoin[month] : 0) * 100).toFixed()  ;
                // }else{
                //     return  0 ;
                // }
               // (item.mostargetjoin.january / item.mosachievementjoin.january)/100

            },
            select_months(mo){ 
                //const d = new Date();  
                if(this.filterForm.month !=''){
                    if(this.filterForm.month ==  mo){
                        return true ;
                    }else{
                        return false ;
                    }
                }else{ 
                    if(this.filterForm.quarter !=''){
                        if(this.filterForm.quarter ==  1  && (mo == 'jan' || mo == 'feb'|| mo == 'mar')){
                            return true ;
                        }else if(this.filterForm.quarter ==  2  && (mo == 'apr' || mo == 'may'|| mo == 'jun')){
                            return true ;
                        }else if(this.filterForm.quarter ==  3  && (mo == 'jul' || mo == 'aug'|| mo == 'sep')){
                            return true ;
                        }else if(this.filterForm.quarter ==  4  && (mo == 'oct' || mo == 'nov'|| mo == 'dec')){
                            return true ;
                        }else{
                            return false ;
                        }
                    }else{
                        return  true
                    }
                }
                // if(mo ==   this.months[ d.getMonth()].id   || mo ==   this.months[ d.getMonth() > 0 ? d.getMonth() - 1 : '' ].id   || mo ==   this.months[ d.getMonth() > 1 ? d.getMonth() - 2 : '' ].id  ){ 
                //     return true ;
                // }else{
                //     return false ;
                // }
            },
            checkConditionKra( length , kpi_index , mos_index  ){ 
                if(kpi_index == 0 &&  mos_index == 0 ){
                    return  true ;
                }else{
                    return  false ;
                } 
            },
            checkConditionKpi( length  , mos_index  ){ 
                if(mos_index == 0 ){
                    return  true ;
                }else{
                    return  false ;
                } 
            },
            async getDept(){
                    let loader = this.$loading.show();
                    this.getDepartments( this.status ).then(({ data }) => { 
                        if(data.success){
                            loader.hide();
                            this.deptItems =  data.data ;
                            this.getItems(); 
                        }else{
                            loader.hide(); 
                        }
                    }); 
            },
            async  getKRA(){   
                await axios.get(this.api_url + "k_r_a_s?dept_id="+this.filterForm.dept_id, {
                        headers: {
                        "Content-Type": "application/json", 
                        Authorization: this.token ? `Bearer ${this.token}` : ""
                        },
                    })
                .then(({ data }) => {  
                    this.getItems();
                    this.kraItem =  data.data ;
                    console.log(this.kraItem );   
                });
            },
            async getKpi(){ 
                console.log(this.filterForm.kra_id);
                await axios.get(this.api_url + "k_p_i_s?kra_id="+this.filterForm.kra_id, {
                            headers: {
                            "Content-Type": "application/json", 
                            Authorization: this.token ? `Bearer ${this.token}` : ""
                            },
                        })
                .then(({ data }) => {  
                    this.getItems();
                        this.kpiItem =  data.data ;
                        console.log(this.roles );   
                });
            }, 

            async getItems() {
                if (this.filterForm.dept_id) {
                    let where = '?'; 
            
                    if (this.filterForm.dept_id) {
                        where += '&dept_id=' + this.filterForm.dept_id;
                    }
                    if (this.filterForm.kra_id) {
                        where += '&kra_id=' + this.filterForm.kra_id;
                    }
                    if (this.filterForm.kpi_id) {
                        where += '&kpi_id=' + this.filterForm.kpi_id;
                    }
                    let loader = this.$loading.show();
                    try {
                        await axios
                            .get(this.api_url + "kra_kpi_mos_list" + where, {
                                headers: {
                                    "Content-Type": "application/json",
                                    Authorization: this.token ? `Bearer ${this.token}` : ""
                                },
                            })
                            .then(({
                                data
                            }) => {
                                if (data.success) {
                                    this.items = data.data ;
                                    console.log( this.items );
                                }
                                loader.hide();
                            });
                    } catch (error) {
                        loader.hide();
                    }
                }
            },
        
        },
        computed: {},
    };
    </script>
    