<template>
    <div>
        <div class="app-content content"> 
        <div class="content-wrapper">
            <div class="content-header row">
                <div class="content-header-left col-12 mb-1 mt-0">
                    <div class="row breadcrumbs-top">
                        <div class="col-12"> 
                            <div class="breadcrumb-wrapper col-12">
                                <ol class="breadcrumb p-0 mb-0">
                                     <li class="breadcrumb-item"><router-link :to="{ path: '/' }"><i class="bx bx-home-alt"></i></router-link>
                                    </li>
                                    <li class="breadcrumb-item  "> <router-link :to="{ path: '/users' }"> Users </router-link>
                                    </li>
                                    <li class="breadcrumb-item active"> New Tour User
                                    </li>
                                    
                                </ol>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div class="content-body">  
                <section class="input-validation">
                    <div class="row">
                        <div class="col-md-12">
                            <div class="card">
                                <div class="card-header">
                                    <h4 class="card-title">New Tour User</h4>
                                </div>
                                <div class="card-content">
                                    <div class="card-body">
                                        <form @submit.prevent="create()">
                                            <div class="row">
                                                <div class="col-md-8">
                                          
                                                    <div class="form-group">
                                                        <label>Name</label>
                                                        <div class="controls">
                                                            <input type="text" name="name" v-model="addForm.name" :class="{  'is-invalid': addForm.errors.has('name'),  }" class="form-control" data-validation-required-message="This field is required" placeholder="Name">
                                                        </div>
                                                    </div>
                                                    <div class="form-group">
                                                        <label>Employee Id</label>
                                                        <div class="controls">
                                                            <input type="text" name="employee_id" v-model="addForm.employee_id" :class="{  'is-invalid': addForm.errors.has('employee_id'),  }" class="form-control" data-validation-required-message="This field is required" placeholder="Employee ID">
                                                        </div>
                                                    </div>
                                                    <div class="form-group">
                                                        <label>Designation</label>
                                                        <div class="controls">
                                                            <input type="text" name="designation" v-model="addForm.designation" :class="{  'is-invalid': addForm.errors.has('designation'),  }" class="form-control" data-validation-required-message="This field is required" placeholder="designation">
                                                        </div>
                                                    </div>
                                                     <div class="form-group">
                                                        <label>Email</label>
                                                        <div class="controls">
                                                            <input type="text" name="email" v-model="addForm.email" :class="{  'is-invalid': addForm.errors.has('email'),  }" class="form-control" data-validation-required-message="This field is required" placeholder="Email">
                                                        </div>
                                                    </div>
                                                    <div class="form-group">
                                                        <label>Password</label>
                                                        <div class="controls">
                                                            <input type="password" name="password" v-model="addForm.password" :class="{  'is-invalid': addForm.errors.has('name'),  }" class="form-control" data-validation-required-message="This field is required" placeholder="Password">
                                                        </div>
                                                    </div>
                                                    <div class="form-group">
                                                        <label>Phone</label>
                                                        <div class="controls">
                                                            <input type="text" name="phone" v-model="addForm.phone" :class="{  'is-invalid': addForm.errors.has('phone'),  }" class="form-control" data-validation-required-message="This field is required" placeholder="Phone">
                                                        </div>
                                                    </div>
                                                </div> 
                                            </div>
                                            <button type="submit" class="btn btn-primary">Submit</button>
                                        </form>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </section>
                <!-- Input Validation end -->
            </div>
        </div>
    </div>
    </div> 
</template>
<script>
//import axios from "../../axios_instance"; 
import { Form } from "vform"; 
export default {
  props: { 
  },
  components: {
    // VueRecaptcha, facebookLogin 
  },
  data() {
    return {
        base_url: window.base_url,
        api_url: window.api_url,    
        DepartmentsItems : [],
        token: this.$localStorage.get("d_token"),
        addForm: new Form({ 
            name: "",  
            email : "",   
            dept_id : "",  
            password : "",
            phone : "",
            role_id : 10,
            wing_id : "",
            employee_id : "",
            designation : "",

        }),
        roles: [] ,  
        WingsItems : [] ,
    };
  },
  created() {  
  },
  methods: { 
    create(){ 
      try {
        let loader = this.$loading.show();
        this.addForm.post(this.api_url + "add_tour_user", {
            headers: {
              "Content-Type": "application/json", 
              Authorization: this.token ? `Bearer ${this.token}` : ""
            },
          }).then((res) => {
              console.log(res);
              if(res.data.success){
                this.$toasted.show(res.data.message, {
                    theme: "bubble",
                    duration: 5000,
                    position: "bottom-right",
                });
              } 
            loader.hide();  
            this.$router.push('/tour_plan_users');
        },(error)=>{
          console.log(error);
           loader.hide(); 
        })
      } catch (error) {
         // loader.hide(); 
        console.log(error);
      }
    } 
  },
  computed: {},
};
</script>
